    "Starting inventory": "Startinventar",
    "Your first interaction": "Deine erste Interaktion",
    "Every map starts with the starting room. Create it with the button on the left.": "Jeder Spielplan beginnt mit dem Startraum. Erstelle ihn mit der Schaltfläche links.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "Wähle eine Kachel in der Palette und lege sie auf den Spielplan; drücke R, um sie zu drehen. Lege fürs Erste zwei verschiedene Kacheln: Sie werden während des Spiels aus der Schachtel genommen und aufgebaut.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "Die Schaltfläche Held (H) legt die Startfelder unserer Abenteurer fest. Wähle 2 bis 4 Felder im Startraum.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "Um den Spielplan nach und nach aufzudecken, brauchen wir einen neuen Raum. Er erscheint, wenn ein Objekt benutzt wird, indem du einen Auslöser programmierst, der einen Raum öffnet. Probieren wir es: Klicke auf die Schaltfläche Objekt (O) und wähle eine Tür. Füge dann einen Auslöser „Einen Raum öffnen“ hinzu.",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "Du hast deine erste Interaktion mit der Umgebung erstellt. Im Spiel öffnet der Held die Tür und gibt die Kacheln des nächsten Raums frei. Jetzt füllen wir diesen Raum: Stelle eine Truhe in einen Raum und programmiere einen Auslöser, der den Spielern Gegenstände gibt (die anderen Schaltflächen und Auslöser warten darauf).",
    "📂 Import a save of the game (.sav)": "📂 Spielstand des Spiels importieren (.sav)",
    "Clear all": "Alles leeren",
    "Search an item…": "Gegenstand suchen …",
    "Only what the party has": "Nur, was die Gruppe hat",
    "skills": "Fertigkeiten",
    "Others": "Andere",
    "Clear the whole starting inventory?": "Das gesamte Startinventar leeren?",
    "Replace the starting inventory with the one of this save?": "Das Startinventar durch das dieses Spielstands ersetzen?",
    "Imported from the save": "Aus dem Spielstand importiert",
    "This file is not a save of the game.": "Diese Datei ist kein Spielstand des Spiels.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "Für eine Gruppe von Veteranen: was sie zu Beginn der Kampagne schon besitzt, gewonnen in früheren Kämpfen. Die Gruppe erhält es, wenn die Kampagne beginnt. Gegenstände kommen aus der Werkstatt (Reiter Gegenstände und Waffen), die Fertigkeiten aus dem Reiter Fertigkeiten (oder aus dem Spiel). Die Gegenstandspools der generierten Spielpläne lassen die einzigartigen Gegenstände aus, die die Gruppe schon hat, und das Spiel gibt nie einen Gegenstand zweimal.",
    "Starting gold": "Startgold",
