    "OGG, MP3 or WAV. Each file plays at its moment in the app: when the monster appears, when it activates, when a hero hits it and when it falls. A moment without a file stays silent. The files are exported next to the map.": "OGG, MP3 oder WAV. Jede Datei wird in der App in ihrem Moment abgespielt: wenn das Monster erscheint, wenn es aktiviert wird, wenn ein Held es trifft und wenn es fällt. Ein Moment ohne Datei bleibt stumm. Die Dateien werden neben den Spielplan exportiert.",
