    "Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "Jetzt fügen wir eine Truhe hinzu und lassen sie der Gruppe ein paar Gegenstände geben. Die anderen Schaltflächen und Auslöser kommen später dran.",
    "Now choose what the chest gives: in its trigger, pick the item (or another option under “What”).": "Wähle jetzt, was die Truhe gibt: Wähle in ihrem Auslöser den Gegenstand (oder eine andere Option unter „Was“).",
