    "Broken links": "Defekte Verbindungen",
    "Elements with no link": "Elemente ohne Verbindung",
    "I know my way around": "Ich kenne mich aus",
    "Are you sure about that?": "Bist du dir sicher?",
    "The tutorial walks you through the editor step by step. If you ever want to revisit it, you can repeat it from ⚙ Settings.": "Das Tutorial führt dich Schritt für Schritt durch den Editor. Wenn du es noch einmal sehen willst, kannst du es unter ⚙ Einstellungen wiederholen.",
    "Yes, skip it": "Ja, überspringen",
    "Skip the tutorial? Everything unlocks now. If you change your mind, ⚙ Settings can run it again.": "Tutorial überspringen? Jetzt wird alles freigeschaltet. Wenn du es dir anders überlegst, kannst du es unter ⚙ Einstellungen erneut starten.",
    "Right here!": "Genau hier!",
    "With Hero (H), click the squares where the heroes start: choose 2 to 4 squares in the starting room.": "Klicke mit Held (H) auf die Felder, auf denen die Helden beginnen: Wähle 2 bis 4 Felder im Startraum.",
    "Nice work!": "Gut gemacht!",
    "The first room is already tied to its door: when a hero opens it, the next room appears on the table. Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "Der erste Raum ist schon an seine Tür gebunden: Wenn ein Held sie öffnet, erscheint der nächste Raum auf dem Tisch. Jetzt fügen wir eine Truhe hinzu und lassen sie der Gruppe ein paar Gegenstände geben. Die anderen Schaltflächen und Auslöser kommen später dran.",
    "Place a Chest (Object) in a room, select it and add the “Give or take away an item” trigger. Choose what it gives the party when it is opened.": "Platziere eine Truhe (Objekt) in einem Raum, wähle sie und füge den Auslöser „Einen Gegenstand geben oder wegnehmen“ hinzu. Wähle, was sie der Gruppe gibt, wenn sie geöffnet wird.",
    "A brand-new room": "Ein brandneuer Raum",
    "The door came with its script and has already created a new room tied to it. Lay out its tiles whenever you like. Now for some monsters: the Enemy button is unlocked.": "Die Tür hat ihr Skript mitgebracht und schon einen neuen, an sie gebundenen Raum erstellt. Lege seine Kacheln aus, wann immer du willst. Jetzt ein paar Monster: Die Schaltfläche Gegner ist freigeschaltet.",
    "Let’s put some monsters in a room: press Enemy (E).": "Stellen wir ein paar Monster in einen Raum: Drücke Gegner (E).",
    "Ops!": "Hoppla!",
    "In the Workshop, press “Import…” and bring in about 10 monsters from the game for this map.": "Drücke in der Werkstatt auf „Importieren …“ und hol etwa 10 Monster aus dem Spiel für diesen Spielplan.",
    "Have a look around the other workshops if you like, then head back to Rooms (◂ Rooms).": "Sieh dich nach Belieben in den anderen Werkstätten um und kehre dann zu Rooms zurück (◂ Rooms).",
    "Now for the room generator. Press ✦ Generate room and click the door that will connect to the new room.": "Jetzt zum Raumgenerator. Drücke ✦ Raum generieren und klicke auf die Tür, die mit dem neuen Raum verbunden wird.",
    "First move the room (drag it or use the arrows) or turn it (R). “Use this” becomes available as soon as the room has moved.": "Verschiebe den Raum zuerst (ziehen oder Pfeiltasten) oder drehe ihn (R). „Diesen verwenden“ wird verfügbar, sobald der Raum bewegt wurde.",
    "You have built rooms by hand, programmed objects, brought in monsters, and generated a room. Now only the campaign remains: it connects maps on the world map, with scenes, choices, and rewards between them. Press “Start a campaign” and the rest of the editor opens up.": "Du hast Räume von Hand gebaut, Objekte programmiert, Monster geholt und einen Raum generiert. Jetzt fehlt nur noch die Kampagne: Sie verbindet Spielpläne auf der Weltkarte, mit Szenen, Entscheidungen und Belohnungen dazwischen. Drücke „Kampagne beginnen“, und der Rest des Editors öffnet sich.",
    "Press “Start a campaign”: everything is unlocked from there.": "Drücke „Kampagne beginnen“: Ab dort ist alles freigeschaltet.",
    "Explore the story flow, a scene (and its boxes), the starting inventory, and the story variables. Then go back to Rooms (◂ Rooms) to finish.": "Erkunde den Handlungsablauf, eine Szene (und ihre Boxen), das Startinventar und die Handlungsvariablen. Kehre dann zu Rooms zurück (◂ Rooms), um abzuschließen.",
    "Open the Workshop": "Werkstatt öffnen",
    "Other finer conditions of this feat in the game (first attack of the round, other heroes…) are kept as they are.": "Andere, feinere Bedingungen dieser Errungenschaft im Spiel (erster Angriff der Runde, andere Helden …) bleiben, wie sie sind.",
    "Otherwise the scene is skipped (the story goes on).": "Sonst wird die Szene übersprungen (die Handlung geht weiter).",
    "Pick a box on the left, or add one.": "Wähle links eine Box oder füge eine hinzu.",
    "Pick a feat on the left, import one from the game, or write a new one.": "Wähle links eine Errungenschaft, importiere eine aus dem Spiel oder schreib eine neue.",
    "Pick a kind on the left.": "Wähle links eine Art.",
    "Pick a recipe on the left, import one from the game, or write a new one.": "Wähle links ein Rezept, importiere eines aus dem Spiel oder schreib ein neues.",
    "Pick another object": "Anderes Objekt wählen",
    "Pillars go in the sockets of an elevated tile of this room at level {n} (the dots on its edges).": "Säulen kommen in die Sockel einer erhöhten Kachel dieses Raums auf Ebene {n} (die Punkte an ihren Kanten).",
    "Pillars hold up elevated tiles: pick the level of that tile ({n} to {n}) on the ribbon first.": "Säulen tragen erhöhte Kacheln: Wähle zuerst die Ebene dieser Kachel ({n} bis {n}) im Menüband.",
    "Place the city…": "Stadt platzieren …",
    "Potions and one-use cards the heroes spend during a quest.": "Tränke und Einwegkarten, die die Helden während eines Abenteuers verbrauchen.",
    "Power of the hero": "Kraft des Helden",
    "Power of the hero (spend to use)": "Kraft des Helden (zum Benutzen ausgeben)",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms.": "Legt während des Spiels etwas auf den Spielplan oder nimmt es herunter: Kacheln, Objekte, Monster, Räume.",
    "Range:": "Reichweite:",
