    "The platform is a box standing on the floor: it needs no pillars.": "Die Plattform ist ein Kasten, der auf dem Boden steht: Sie braucht keine Säulen.",
    "The rune: damage, damage types and power": "Die Rune: Schaden, Schadensarten und Kraft",
    "First effect: an ability that may trigger on hits": "Erster Effekt: eine Fähigkeit, die bei Treffern auslösen kann",
    "Second effect: another ability that may trigger on hits": "Zweiter Effekt: eine weitere Fähigkeit, die bei Treffern auslösen kann",
    "The spaces work together, by the game's rule for random spawns: one budget of points for all of them (intensity ÷ {n} × heroes × {n} × progression, Map setup › Balancing) decides how many monsters enter and how strong. All may enter, or just one strong monster.": "Die Felder wirken zusammen, nach der Spielregel für zufälliges Erscheinen: Ein Punktebudget für alle (Intensität ÷ {n} × Helden × {n} × Fortschritt, Spielplan-Einstellungen › Ausbalancierung) bestimmt, wie viele Monster erscheinen und wie stark sie sind. Alle können erscheinen oder nur ein starkes Monster.",
    "The workshop has no items yet.": "Die Werkstatt hat noch keine Gegenstände.",
    "The workshop has no items yet: create or import them in the Items tab.": "Die Werkstatt hat noch keine Gegenstände: Erstelle oder importiere sie im Reiter Gegenstände.",
    "The workshop has no items: import or create them in the Items tab.": "Die Werkstatt hat keine Gegenstände: Importiere oder erstelle sie im Reiter Gegenstände.",
