    "Used, it leaves the board (like a point of interest in the game).": "Nach der Benutzung verlässt es den Spielplan (wie ein interessanter Ort im Spiel).",
    "Using this object counts as an objective of the room (listed and ticked). Older maps only: use “{q}”.": "Die Benutzung dieses Objekts zählt als Aufgabe des Raums (aufgeführt und abgehakt). Nur ältere Spielpläne: Nutze „{Q}“.",
