    "Worn by a hero: a card with its rule, kept in the party’s inventory.": "Von einem Helden getragen: eine Karte mit ihrer Regel, im Inventar der Gruppe aufbewahrt.",
    "Writes the .bmap (download), then clears.": "Schreibt die .bmap (Download) und leert dann.",
