    "Tiles can stand at levels 1, 2 and 3 (the level buttons) on": "Kacheln können auf den Ebenen 1, 2 und 3 (die Ebenen-Schaltflächen) stehen, auf",
    "; the app counts the pillars your boxes have.": "; die App zählt die Säulen, die deine Schachteln haben.",
    "pillars (P)": "Säulen (P)",
    "Counts": "Zählungen",
    "keep a number during the map (keys found, seals broken): triggers add to them, and a map objective can wait for the total.": "halten während des Spielplans eine Zahl fest (gefundene Schlüssel, gebrochene Siegel): Auslöser zählen dazu, und eine Spielplanaufgabe kann auf die Summe warten.",
    "Export map": "Spielplan exportieren",
    "The": "Die",
    "Workshop (⚒)": "Werkstatt (⚒)",
    "Map setup": "Spielplan-Einstellungen",
    "Start a campaign": "Kampagne beginnen",
    "Press": "Drücke",
    "3D": "3D",
    "Hero (H)": "Held (H)",
    "Enemy (E)": "Gegner (E)",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "Wenn der Raum beginnt, füllt das Spiel diese Felder nach seiner eigenen Regel für zufälliges Erscheinen: Punkte = Intensität ÷ {n} × Helden × {n} × Fortschritt",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression": "Wenn der Raum geöffnet wird, füllt das Spiel diese Felder nach seiner eigenen Regel für zufälliges Erscheinen: Punkte = Intensität ÷ {n} × Helden × {n} × Fortschritt",
    "When the room opens, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Wenn der Raum geöffnet wird, füllt das Spiel diese Felder nach seiner eigenen Regel für zufälliges Erscheinen: Punkte = Intensität ÷ {n} × Helden × {n} × Fortschritt; es nimmt den höchsten Rang aus dem Bereich des Spielplans, den die Punkte bezahlen (Kosten {n}, {n}, {n}, {n}, {n}, {n} …), und Monster aus dem Pool mit diesem Rang erscheinen, eines pro Feld (bis zu {n}), solange die Punkte reichen. Übrige Punkte gehen an den nächsten ausbalancierten Raum. Alle können erscheinen oder nur ein starkes Monster.",
    "{n} balanced spaces in this room": "{n} ausbalancierte Felder in diesem Raum",
    "{n} monsters, tier {n}": "{n} Monster, Rang {n}",
    "{n} monster, tier {n}": "{n} Monster, Rang {n}",
    "{n} monsters, tier {n} (no more miniatures)": "{n} Monster, Rang {n} (keine Miniaturen mehr)",
    "none: no free miniature": "keine: keine freie Miniatur",
    "Room {n} · space {n},{n}": "Raum {n} · Feld {n},{n}",
    "{n} rooms · side quest": "{n} Räume · Nebenabenteuer",
    "A change applies while this campaign is played, to every copy of the part, also the ones bought or found later.": "Eine Änderung gilt, solange diese Kampagne gespielt wird, für jedes Exemplar des Teils, auch die später gekauften oder gefundenen.",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "Wähle eine Waffenart, dann ihre Köpfe, Schäfte oder Griffe. Was du änderst, gilt, solange diese Kampagne gespielt wird (für jedes Exemplar des Teils, auch die später gekauften oder gefundenen); was du unverändert lässt, bleibt wie im Spiel.",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this campaign is played (to every copy of the part, also the ones bought or found later)": "Wähle eine Waffenart, dann ihre Köpfe, Schäfte oder Griffe. Was du änderst, gilt, solange diese Kampagne gespielt wird (für jedes Exemplar des Teils, auch die später gekauften oder gefundenen)",
    "Here you prepare the monsters of this campaign. Only the monsters listed here can be placed on the board or drawn from the spawn pool.": "Hier bereitest du die Monster dieser Kampagne vor. Nur die hier aufgeführten Monster können auf den Spielplan gestellt oder aus dem Erscheinungspool gezogen werden.",
    "A short list is easier to balance and to test; add more as the campaign grows.": "Eine kurze Liste ist leichter auszubalancieren und zu testen; füge mehr hinzu, wenn die Kampagne wächst.",
    "add more as the campaign grows.": "füge mehr hinzu, wenn die Kampagne wächst.",
    "Here you choose the items of this campaign: import them from the game, change them (name, rarity, value, damage, abilities) or create your own. Only the items listed here can be dropped by monsters, found or given by triggers, and the": "Hier wählst du die Gegenstände dieser Kampagne: Importiere sie aus dem Spiel, ändere sie (Name, Seltenheit, Wert, Schaden, Fähigkeiten) oder erstelle eigene. Nur die hier aufgeführten Gegenstände können von Monstern fallen gelassen, gefunden oder durch Auslöser vergeben werden, und der",
    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "Frühe starke Gegenstände machen die Kämpfe leicht; zu wenige oder schwache lassen die Helden hinter den Monstern zurück. Wähle sie mit Absicht und denk an den Fortschritt der Helden im Lauf der Kampagne.",
    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the campaign.": "zu wenige oder schwache lassen die Helden hinter den Monstern zurück. Wähle sie mit Absicht und denk an den Fortschritt der Helden im Lauf der Kampagne.",
    "Each sheet changes one of the six heroes of the game while this campaign is played: name, portrait and animated figure. Their weapons are in the Weapons tab. What you leave as it is stays as in the game.": "Jedes Blatt ändert einen der sechs Helden des Spiels, solange diese Kampagne gespielt wird: Name, Porträt und animierte Figur. Ihre Waffen sind im Reiter Waffen. Was du unverändert lässt, bleibt wie im Spiel.",
    "The item workshop": "Die Gegenstandswerkstatt",
    "The monster workshop": "Die Monsterwerkstatt",
    "is what random-item triggers draw from.": "ist das, woraus Auslöser für Zufallsgegenstände ziehen.",
    "The selection of available items is essential for the balance of the game.": "Die Auswahl der verfügbaren Gegenstände ist entscheidend für das Gleichgewicht des Spiels.",
    "The party has it from the start of the campaign (the heroes pick it in the hero choice)": "Die Gruppe hat es ab Beginn der Kampagne (die Helden wählen es bei der Heldenwahl)",
