    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "die Intensität der Räume mit Monstern und der Auslöser, die Monster aus dem Pool rufen, alle um denselben Schritt (von −6 bis +6, immer innerhalb von 1 bis 10);",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "die Ränge für 1–2, 3 und 4 Helden der von Hand platzierten Monster, nach der Spielregel (wie ⚖ Ausbalancieren bei einem Monster).",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "der Kampagnenfortschritt, die Monster- und Gegenstandspools, die Monster selbst, die Objekte, die Auslöser und die Texte.",
