    "Name": "Name",
    "New rooms are born from an object: select it, add the trigger “{q}”. Pick a room here before touching what is in it.": "Neue Räume entstehen aus einem Objekt: Wähle es und füge den Auslöser „{Q}“ hinzu. Wähle hier einen Raum, bevor du anrührst, was darin ist.",
