    "). Which monster of the pool enters is drawn in the game.": "). Welches Monster aus dem Pool erscheint, wird im Spiel ausgelost.",
    "+ Another space": "+ Weiteres Feld",
    "Intensity of this room": "Intensität dieses Raums",
    "Tier range {n}–{n}, campaign progression {n} (": "Rangbereich {n}–{n}, Kampagnenfortschritt {n} (",
    "What the game would do": "Was das Spiel tun würde",
    "When the group is defeated": "Wenn die Gruppe besiegt ist",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Wenn der Raum beginnt, füllt das Spiel diese Felder nach seiner eigenen Regel für zufälliges Erscheinen: Punkte = Intensität ÷ {n} × Helden × {n} × Fortschritt; es nimmt den höchsten Rang aus dem Bereich des Spielplans, den die Punkte bezahlen (Kosten {n}, {n}, {n}, {n}, {n}, {n} …), und Monster aus dem Pool mit diesem Rang erscheinen, eines pro Feld (bis zu {n}), solange die Punkte reichen. Übrige Punkte gehen an den nächsten ausbalancierten Raum. Alle können erscheinen oder nur ein starkes Monster.",
    "change": "ändern",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "es nimmt den höchsten Rang aus dem Bereich des Spielplans, den die Punkte bezahlen (Kosten {n}, {n}, {n}, {n}, {n}, {n} …), und Monster aus dem Pool mit diesem Rang erscheinen, eines pro Feld (bis zu {n}), solange die Punkte reichen. Übrige Punkte gehen an den nächsten ausbalancierten Raum. Alle können erscheinen oder nur ein starkes Monster.",
    "{n} (= spaces, default)": "{n} (= Felder, Standard)",
    "{n} balanced space in this room": "{n} ausbalanciertes Feld in diesem Raum",
    "{n} hero": "{n} Held",
    "{n} monster, tier {n} (too few points: the minimum)": "{n} Monster, Rang {n} (zu wenige Punkte: das Minimum)",
    "Opened by:": "Geöffnet durch:",
    "Remove this room": "Diesen Raum entfernen",
    "Text when revealed": "Text beim Aufdecken",
