    "Text after the board is set up": "Text nach dem Aufbau des Spielplans",
    "What the heroes find in it: a person, an object (the interaction tokens)": "Was die Helden darin finden: eine Person, ein Objekt (die Interaktionsmarker)",
    "Tile {n} is in another room: reusing it here needs that room removed first": "Kachel {n} ist in einem anderen Raum: Um sie hier wiederzuverwenden, muss dieser Raum zuerst entfernt werden",
    "give one an “{q}” trigger": "gib einem einen Auslöser „{Q}“",
    "no object opens this room; give one an “{q}” trigger": "kein Objekt öffnet diesen Raum; gib einem einen Auslöser „{Q}“",
