    "Opens": "Öffnet",
    "a new room can be created here too.": "hier kann auch ein neuer Raum erstellt werden.",
    "opened by “{q}”": "geöffnet durch „{Q}“",
    "A scene (dialogue boxes)": "Eine Szene (Dialogboxen)",
    "A scene of dialogue boxes (like the story flow), your own film full screen, a sound effect of the game or your own sound file. (a scene, a video, a sound)": "Eine Szene aus Dialogboxen (wie der Handlungsablauf), dein eigener Film im Vollbild, ein Soundeffekt des Spiels oder deine eigene Sounddatei. (eine Szene, ein Video, ein Sound)",
    "A sound (game effect or your own file)": "Ein Sound (Spieleffekt oder eigene Datei)",
    "A tile": "Eine Kachel",
    "A video (your own film)": "Ein Video (dein eigener Film)",
    "Add / Remove…": "Hinzufügen / Entfernen …",
    "Add a trigger to “{q}”": "Einen Auslöser zu „{Q}“ hinzufügen",
    "Add or remove?": "Hinzufügen oder entfernen?",
    "Add what?": "Was hinzufügen?",
    "Adds to (or removes from) the item pool or the monster spawn pool of the map, for the rest of the map. (item, monster spawn)": "Fügt dem Gegenstandspool oder dem Monster-Erscheinungspool des Spielplans etwas hinzu (oder entfernt etwas daraus), für den Rest des Spielplans. (Gegenstand, Monstererscheinen)",
    "Add…": "Hinzufügen …",
