    "Monster spawn": "Monstererscheinen",
    "Play a scene, video or sound": "Szene, Video oder Sound abspielen",
    "Play what?": "Was abspielen?",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, spawn monsters, a tile, a room, an object, a monster)": "Legt während des Spiels etwas auf den Spielplan oder nimmt es herunter: Kacheln, Objekte, Monster, Räume. (eine Kachel, ein Objekt, Monster erscheinen lassen, eine Kachel, einen Raum, ein Objekt, ein Monster)",
    "Remove…": "Entfernen …",
    "Something appears on the board: a tile, an object or monsters. (a tile, an object, spawn monsters)": "Etwas erscheint auf dem Spielplan: eine Kachel, ein Objekt oder Monster. (eine Kachel, ein Objekt, Monster erscheinen lassen)",
    "Takes something off the board: a tile, a room, an object or monsters. (a tile, a room, an object, a monster)": "Nimmt etwas vom Spielplan: eine Kachel, einen Raum, ein Objekt oder Monster. (eine Kachel, einen Raum, ein Objekt, ein Monster)",
    "What happens when a hero uses this object. Several triggers run in order.": "Was passiert, wenn ein Held dieses Objekt benutzt. Mehrere Auslöser werden der Reihe nach ausgeführt.",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "Legt während des Spiels etwas auf den Spielplan oder nimmt es herunter: Kacheln, Objekte, Monster, Räume. (eine Kachel, ein Objekt, eine Kachel, einen Raum, ein Objekt, ein Monster)",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "Was einmal passiert, wenn die Zählung {n} erreicht (die Summe des Zählers). Mehrere Auslöser werden der Reihe nach ausgeführt.",
    "When the balanced group is defeated: “{q}”": "Wenn die ausbalancierte Gruppe besiegt ist: „{Q}“",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "Ein Ziel auf diesem Spielplan, angekündigt, wenn das Monster besiegt ist, und bei den Aufgaben aufgeführt. Eine Aufgabe beendet den Spielplan nicht: Das tut die Mission (Spielplan-Einstellungen). Dort kann eine Aufgabe als Mission gewählt werden.",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "Ab der Niederlage des Monsters führt der Rundenzähler die Auslöser darin aus: alle N Runden (so oft du festlegst oder bis zum Ende des Spielplans) oder einmal, N Runden später. Für eine Welle lege „{Q}“ hinein: Das Erscheinen hat sein eigenes „{Q}“.",
    "When this monster is defeated: “{q}”": "Wenn dieses Monster besiegt ist: „{Q}“",
    "If the test fails: “{q}”": "Wenn die Probe misslingt: „{Q}“",
    "After answer {n}: “{q}”": "Nach Antwort {n}: „{Q}“",
    "When the rounds come: “{q}”": "Wenn die Runden erreicht sind: „{Q}“",
