    "Takes one tile off the board with everything on it (objects, pillars, monsters). Frees it for reuse in a later room.": "Nimmt eine Kachel mit allem darauf vom Spielplan (Objekte, Säulen, Monster). Gibt sie für einen späteren Raum wieder frei.",
