    "None yet (“{q}” above). A new haft is an item: the party gets it from a “{q}” trigger or crafts it with a recipe, and fits it in the armory.": "Noch keiner („{Q}“ oben). Ein neuer Schaft ist ein Gegenstand: Die Gruppe bekommt ihn von einem Auslöser „{Q}“ oder stellt ihn mit einem Rezept her und baut ihn in der Rüstkammer ein.",
    "None yet (“{q}” above). A new grip is an item: the party gets it from a “{q}” trigger or crafts it with a recipe, and fits it in the armory.": "Noch keiner („{Q}“ oben). Ein neuer Griff ist ein Gegenstand: Die Gruppe bekommt ihn von einem Auslöser „{Q}“ oder stellt ihn mit einem Rezept her und baut ihn in der Rüstkammer ein.",
