    "The shop opens in its own window over the board; the next triggers run when it closes. To charge an entrance or limit who may enter, put a requirement on this trigger.": "Der Händler öffnet sich in einem eigenen Fenster über dem Spielplan; die nächsten Auslöser werden ausgeführt, wenn es sich schließt. Um Eintritt zu verlangen oder zu begrenzen, wer hinein darf, gib diesem Auslöser eine Voraussetzung.",
    "The armory opens in its own window over the board; the next triggers run when it closes. Heroes whose weapons this map sets (Workshop) keep them.": "Die Rüstkammer öffnet sich in einem eigenen Fenster über dem Spielplan; die nächsten Auslöser werden ausgeführt, wenn es sich schließt. Helden, deren Waffen dieser Spielplan festlegt (Werkstatt), behalten sie.",
