    "The item pool of the map": "Der Gegenstandspool des Spielplans",
    "(the campaign’s current stock: what the party buys here leaves the city’s shop, what it sells goes there, as in the game)": "(das aktuelle Angebot der Kampagne: Was die Gruppe hier kauft, verlässt den Händler der Stadt, was sie verkauft, kommt dorthin, wie im Spiel)",
