    "“{q}” can now be used every time (change it in “{q}”); the trigger says how many times the shop opens.": "„{Q}“ kann jetzt jedes Mal benutzt werden (ändern unter „{Q}“); der Auslöser legt fest, wie oft sich der Händler öffnet.",
