    "Armor of the workshop": "Rüstung der Werkstatt",
    "Assemble the Sword": "Das Schwert zusammensetzen",
    "At the end of each round": "Am Ende jeder Runde",
    "At the end of the quest": "Am Ende des Abenteuers",
    "{n} in the roster": "{n} im Kader",
    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "Die sechs Profile des Spiels (Klasse, Waffen, Fertigkeiten und Errungenschaften) kommen in die Kampagne. Jedes wird vom Helden des Spiels gespielt (wie im Spiel) oder von einem Helden deines Kaders, der auf dem eigenen Blatt des Helden eingesetzt wird.",
    "The six profiles of the game (class, weapons, skills and feats) go into the map. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "Die sechs Profile des Spiels (Klasse, Waffen, Fertigkeiten und Errungenschaften) kommen in den Spielplan. Jedes wird vom Helden des Spiels gespielt (wie im Spiel) oder von einem Helden deines Kaders, der auf dem eigenen Blatt des Helden eingesetzt wird.",
    "In the campaign": "In der Kampagne",
    "In the map": "Im Spielplan",
    "Roster": "Kader",
    "+ New hero": "+ Neuer Held",
    "From an NPC…": "Aus einem NSC …",
    "profile": "Profil",
    "the game’s hero, out: another plays this profile": "der Held des Spiels, draußen: Ein anderer spielt dieses Profil",
    "not in the profiles": "nicht in den Profilen",
    "New hero": "Neuer Held",
    "The Workshop has no NPC yet.": "Die Werkstatt hat noch keinen NSC.",
    "A hero from an NPC": "Ein Held aus einem NSC",
