    "hero in the roster.": "Held im Kader.",
    "plays the profile of": "spielt das Profil von",
    "in the roster": "im Kader",
    "out: played by": "draußen: gespielt von",
    "Profile in the campaign": "Profil in der Kampagne",
    "Profile in the map": "Profil im Spielplan",
    "None: stays in the roster": "Keins: bleibt im Kader",
    "Delete hero": "Held löschen",
    "The animated drawing of the game hero of its profile.": "Die animierte Zeichnung des Spielhelden seines Profils.",
    "(the profile’s)": "(die des Profils)",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "Jede Waffe hat im Spiel einen Helden (ihre Teile, der Händler, das Inventar und die Errungenschaften folgen ihm). Wählst du die Waffe eines anderen Helden, erhält dieser im Tausch diese hier. Die Werte kommen von den Waffen: Sie werden im Reiter Waffen geändert. Die Waffen gehören zum Profil: Sie bleiben bei ihm, wenn der Held geht.",
    "The weapons belong to the profile: they stay with it if the hero leaves.": "Die Waffen gehören zum Profil: Sie bleiben bei ihm, wenn der Held geht.",
    "went back to the roster.": "ist in den Kader zurückgekehrt.",
    "Who plays this profile": "Wer dieses Profil spielt",
    "the game’s hero": "der Held des Spiels",
    "now in the profile of": "jetzt im Profil von",
    "Pick a hero of the roster to play this profile in the place of the game’s hero.": "Wähle einen Helden des Kaders, der dieses Profil anstelle des Spielhelden spielt.",
    "now plays the profile of": "spielt jetzt das Profil von",
    "is back in the profile.": "ist wieder im Profil.",
    "Heads, hafts and grips of the weapons, imported in a package or made here: they are in the Weapons tab, under the weapon they belong to.": "Köpfe, Schäfte und Griffe der Waffen, in einem Paket importiert oder hier erstellt: Sie sind im Reiter Waffen, unter der Waffe, zu der sie gehören.",
    "{n} new part(s)": "{n} neue(s) Teil(e)",
    "Charms a hero carries; some have an effect the app applies.": "Glücksbringer, die ein Held trägt; manche haben einen Effekt, den die App anwendet.",
    "Crafting materials: loot is paid in them and recipes cost them.": "Handwerksmaterialien: Beute wird in ihnen ausgezahlt, und Rezepte kosten sie.",
    "Tick several entries of this tab and delete them at once": "Mehrere Einträge dieses Reiters anhaken und auf einmal löschen",
    "🗑 Delete several…": "🗑 Mehrere löschen …",
    "Delete several": "Mehrere löschen",
    "This tab has nothing to delete in a batch.": "In diesem Reiter gibt es nichts zum Sammellöschen.",
    "Nothing to delete in this tab.": "Nichts zu löschen in diesem Reiter.",
    "Weapon": "Waffe",
    "Origin": "Herkunft",
    "Made here or in a package": "Hier oder in einem Paket erstellt",
    "Imported from the game": "Aus dem Spiel importiert",
