    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "Ziehe die Teile, um die Waffe nach deinem Wunsch zusammenzusetzen; das Mausrad (oder der Schieberegler) ändert die Größe des gewählten Teils, Shift+Mausrad, Q/E oder der Drehregler drehen es, die Pfeiltasten schieben es. Ein Teil erscheint nur in seiner eigenen Box: Was hinausragt, wird abgeschnitten (blass gezeigt).",
    "Drag the pieces to put the weapon together, forge the template and bake the pictures": "Ziehe die Teile, um die Waffe zusammenzusetzen, schmiede die Vorlage und erzeuge die Bilder",
