    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later)": "Wähle eine Waffenart, dann ihre Köpfe, Schäfte oder Griffe. Was du änderst, gilt, solange dieser Spielplan gespielt wird (für jedes Exemplar des Teils, auch die später gekauften oder gefundenen)",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "Wähle eine Waffenart, dann ihre Köpfe, Schäfte oder Griffe. Was du änderst, gilt, solange dieser Spielplan gespielt wird (für jedes Exemplar des Teils, auch die später gekauften oder gefundenen); was du unverändert lässt, bleibt wie im Spiel.",
