    "Potions and one-use cards the heroes spend during a quest. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Tränke und Einwegkarten, die die Helden während eines Abenteuers verbrauchen. Nur in der Werkstatt aufgeführte Gegenstände können durch Auslöser, Belohnungen und Dialoge vergeben, von Monstern fallen gelassen oder hergestellt werden.",
