    "Rarity": "Seltenheit",
    "Recalculate the other tiers from this one with the game's own curve: health grows ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} per tier, defense +{n} per tier, attack +{n} up to tier {n} and then +{n} every two tiers. With this tier alone, it creates the tiers up to {n}": "Berechne die anderen Ränge aus diesem mit der eigenen Kurve des Spiels neu: Lebenspunkte wachsen ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} pro Rang, Verteidigung +{n} pro Rang, Angriff +{n} bis Rang {n} und dann +{n} alle zwei Ränge. Gibt es nur diesen Rang, werden die Ränge bis {n} erstellt",
