    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the map.": "Frühe starke Gegenstände machen die Kämpfe leicht; zu wenige oder schwache lassen die Helden hinter den Monstern zurück. Wähle sie mit Absicht und denk an den Fortschritt der Helden im Lauf des Spielplans.",
