    "The monster’s own rule shown in the attack window, like the bandit’s “{q}”. Leave empty to keep the one of the behaviour monster.": "Die eigene Regel des Monsters, im Angriffsfenster gezeigt, wie das „{Q}“ des Banditen. Leer lassen, um die des Verhaltensmonsters zu behalten.",
    "The party has it from the start of the map (the heroes pick it in the hero choice)": "Die Gruppe hat es ab Beginn des Spielplans (die Helden wählen es bei der Heldenwahl)",
