    "What the monster does on its turn, in order; “{q}” chains them. Speed, damage, aim, attack, range, healing, shield, initiative and range type are the numbers the app uses; the text is what the players read.": "Was das Monster in seinem Zug tut, der Reihe nach; „{Q}“ verkettet sie. Geschwindigkeit, Schaden, Zielen, Angriff, Reichweite, Heilung, Schild, Initiative und Reichweitenart sind die Zahlen, die die App nutzt; der Text ist, was die Spieler lesen.",
