    "Write plain text. The buttons put in the names the app fills in ([monster] = the name of this monster, [hero] = the name of the hero it targets (or another name the app fills in)) and the game icons. Rule words like scar, terrify or focus become the game’s highlighted terms by themselves.": "Schreib einfachen Text. Die Schaltflächen fügen die Namen ein, die die App ausfüllt ([monster] = der Name dieses Monsters, [hero] = der Name des Helden, den es ins Ziel nimmt (oder ein anderer Name, den die App ausfüllt)), und die Symbole des Spiels. Regelwörter wie brandmarken, verängstigen oder fokussieren werden von selbst zu den hervorgehobenen Begriffen des Spiels.",
