    "the text is what the players read.": "der Text ist, was die Spieler lesen.",
    "the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "das Mausrad (oder der Schieberegler) ändert die Größe des gewählten Teils, Shift+Mausrad, Q/E oder der Drehregler drehen es, die Pfeiltasten schieben es. Ein Teil erscheint nur in seiner eigenen Box: Was hinausragt, wird abgeschnitten (blass gezeigt).",
    "three parts": "drei Teile",
    "tier": "Rang",
    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the map.": "zu wenige oder schwache lassen die Helden hinter den Monstern zurück. Wähle sie mit Absicht und denk an den Fortschritt der Helden im Lauf des Spielplans.",
    "turns each piece into a picture of the exact size of its box and puts it in the weapon.": "verwandelt jedes Teil in ein Bild in der genauen Größe seiner Box und setzt es in die Waffe.",
