    "Here you prepare the monsters of this map. Only the monsters listed here can be placed on the board or drawn from the spawn pool.": "Hier bereitest du die Monster dieses Spielplans vor. Nur die hier aufgeführten Monster können auf den Spielplan gestellt oder aus dem Erscheinungspool gezogen werden.",
