    "✎ or double-click opens the card": "✎ oder Doppelklick öffnet die Karte",
    "📜 Original maps": "📜 Originalspielpläne",
    "The quests of the game, converted into editable maps": "Die Abenteuer des Spiels, in bearbeitbare Spielpläne umgewandelt",
    "✦ Generate room": "✦ Raum generieren",
    "Build a room from an archetype: three candidates to pick from": "Einen Raum aus einem Archetyp bauen: drei Kandidaten zur Auswahl",
    "✦ Generate map": "✦ Spielplan generieren",
    "✦ Generate map (experimental)": "✦ Spielplan generieren (experimentell)",
    "Generate a map (experimental)": "Einen Spielplan generieren (experimentell)",
    "Original maps": "Originalspielpläne",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "Die Originalspielpläne des Spiels liest der Bigorna-Mod aus deiner eigenen Kopie des Spiels: Starte das Spiel einmal mit installiertem Mod (der Titelbildschirm bereitet sie vor) und öffne dann den Editor erneut aus dem Ordner Editor des Spiels.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "Die Abenteuer des Spiels, in Spielpläne des Editors umgewandelt: Kacheln, Objekte, Räume, Monster und die Logik, die die Auslöser ausdrücken können.",
    "Each map comes with notes on what was simplified (Map setup).": "Zu jedem Spielplan gibt es Notizen dazu, was vereinfacht wurde (Spielplan-Einstellungen).",
    "The texts come in the language of your game.": "Die Texte erscheinen in der Sprache deines Spiels.",
    "Open": "Öffnen",
    "Could not read that map": "Dieser Spielplan konnte nicht gelesen werden",
    "The conversion failed": "Die Umwandlung ist fehlgeschlagen",
    "Replace the map on screen with the original map? Export it first if you want to keep it.": "Den Spielplan auf dem Bildschirm durch den Originalspielplan ersetzen? Exportiere ihn vorher, wenn du ihn behalten willst.",
    "Original map opened": "Originalspielplan geöffnet",
    "See the import notes in Map setup.": "Sieh dir die Importnotizen in den Spielplan-Einstellungen an.",
    "Import notes": "Importnotizen",
