    "Monster types": "Monstertypen",
    "Item cards": "Gegenstandskarten",
    "The generators use only what is in the Workshop: its monsters, items, materials and objects, within the chosen boxes.": "Die Generatoren nutzen nur, was in der Werkstatt ist: ihre Monster, Gegenstände, Materialien und Objekte, innerhalb der gewählten Schachteln.",
    "Trim it in the Workshop as you like.": "Kürze sie in der Werkstatt nach Belieben.",
