    "Less walking back": "Weniger Rückweg",
    "a spiral": "eine Spirale",
    "return runes": "Rückkehrrunen",
    "waystones": "Wegsteine",
    "lever to the attic": "Hebel zum Dachboden",
    "viaduct": "Viadukt",
    "🧱 Pieces in your boxes…": "🧱 Teile in deinen Schachteln …",
    "How many of each piece you have: the generators use only these, and the object buttons show how many are on the table while a room is open. A blank field uses the estimate for your boxes (shown faded); ∞ means no limit. Two boxes, or a piece made by hand: raise the number.": "Wie viele von jedem Teil du hast: Die Generatoren nutzen nur diese, und die Objektschaltflächen zeigen, wie viele auf dem Tisch sind, während ein Raum offen ist. Ein leeres Feld nutzt die Schätzung für deine Schachteln (blass gezeigt); ∞ heißt unbegrenzt. Zwei Schachteln oder ein selbstgebautes Teil: Erhöhe die Zahl.",
    "3D objects and tokens": "3D-Objekte und Marker",
    "Pieces in your boxes": "Teile in deinen Schachteln",
    "Piece counts saved.": "Teileanzahl gespeichert.",
    "Pillars that hold tiles": "Säulen, die Kacheln tragen",
    "Map tiles": "Spielplankacheln",
    "Workshop pieces": "Werkstatt-Teile",
    "level": "Ebene",
    "Successes add up over tries (a lock, a heavy door: each try brings them closer)": "Erfolge summieren sich über Versuche (ein Schloss, eine schwere Tür: Jeder Versuch bringt sie näher)",
    "Use the counts of the boxes": "Die Anzahl der Schachteln verwenden",
    "Piece counts: those of the boxes chosen.": "Teileanzahl: die der gewählten Schachteln.",
    "Put the middle of the archway on tiles of this room at level {n} (its feet may hang off the tiles).": "Stelle die Mitte des Torbogens auf Kacheln dieses Raums auf Ebene {n} (seine Füße dürfen über die Kacheln hinausragen).",
    "Workshop object": "Werkstatt-Objekt",
