    "Package": "Paket",
    "✎ Stats": "✎ Werte",
    "Underlay cards": "Unterlagenkarten",
    "This belongs to the package": "Das gehört zum Paket",
    "Change it: a version of yours, with a new ID": "Ändern: eine eigene Version mit neuer ID",
    "Create a clone": "Einen Klon erstellen",
    "The package’s entry stays as the creator made it.": "Der Eintrag des Pakets bleibt, wie der Ersteller ihn gemacht hat.",
    "Clone made: it is yours to change.": "Klon erstellt: Er gehört dir, du kannst ihn ändern.",
    "Now this version is yours, with a new ID: change it here.": "Jetzt gehört diese Version dir, mit neuer ID: Ändere sie hier.",
    "An original of the game: it stays as the game has it.": "Ein Original des Spiels: Es bleibt, wie das Spiel es hat.",
    "Change it here: changed, it becomes yours, with the same id (what uses it gets your version; the package’s file stays as it is). To take it out, remove the package (📚 My packages).": "Hier ändern: Sobald du es änderst, gehört es dir, mit derselben ID (was es nutzt, bekommt deine Version; die Datei des Pakets bleibt, wie sie ist). Um es herauszunehmen, entferne das Paket (📚 Meine Pakete).",
    "It replaces the map on screen, fully editable.": "Er ersetzt den Spielplan auf dem Bildschirm, voll bearbeitbar.",
    "A whole map: why the heroes go in (premise), what they must do to win (objective), what changes along the way (extra rule), how the tension grows and the end. It replaces the map on screen, fully editable.": "Ein ganzer Spielplan: warum die Helden hineingehen (Prämisse), was sie tun müssen, um zu gewinnen (Aufgabe), was sich unterwegs ändert (Zusatzregel), wie die Spannung wächst und das Ende. Er ersetzt den Spielplan auf dem Bildschirm, voll bearbeitbar.",
    "Add to the campaign": "Zur Kampagne hinzufügen",
    "Monsters in a room": "Monster in einem Raum",
    "A long, narrow way: whoever holds the narrow part holds the room.": "Ein langer, schmaler Weg: Wer die enge Stelle hält, hält den Raum.",
    "Wide and open: a straight fight with room to move.": "Weit und offen: ein direkter Kampf mit Platz zum Bewegen.",
    "Few or no monsters, several points of interest to search and a clue.": "Wenige oder keine Monster, mehrere interessante Orte zum Durchsuchen und ein Hinweis.",
    "The reward, guarded or not: chests at the back, a price to reach them.": "Die Belohnung, bewacht oder nicht: Truhen hinten, ein Preis, um sie zu erreichen.",
    "A calm place to breathe, heal and talk: no monsters, a little to find.": "Ein ruhiger Ort zum Durchatmen, Heilen und Reden: keine Monster, ein wenig zu finden.",
    "The last room: large, with cover and a strong foe at the back.": "Der letzte Raum: groß, mit Deckung und einem starken Gegner hinten.",
    "The way is blocked by water, fire or rubble: go around, or through it.": "Der Weg ist durch Wasser, Feuer oder Schutt versperrt: herum oder hindurch.",
    "A raised platform over the floor: whoever holds the height sees everything.": "Eine erhöhte Plattform über dem Boden: Wer die Höhe hält, sieht alles.",
    "Moving: drag the room · R turns it · Esc or a click outside ends it": "Verschieben: Ziehe den Raum · R dreht ihn · Esc oder ein Klick außerhalb beendet es",
    "Click the outline to move the room · R turns it": "Klicke auf den Umriss, um den Raum zu verschieben · R dreht ihn",
    "The room has no tiles to turn.": "Der Raum hat keine Kacheln zum Drehen.",
    "Turned, the room overlapped another one: it stayed as it was.": "Gedreht hätte der Raum einen anderen überlappt: Er bleibt, wie er war.",
    "Room turned 90°, with everything in it.": "Raum um 90° gedreht, mit allem darin.",
    "Delete anyway": "Trotzdem löschen",
    "First move all its triggers to another object (you click it), then delete.": "Zuerst alle seine Auslöser auf ein anderes Objekt verschieben (du klickst darauf), dann löschen.",
