    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "Das löscht alles, was der Editor aufbewahrt: den Spielplan oder die Kampagne auf dem Bildschirm, die Werkstatt (Monster, Gegenstände, Materialien, Objekte, importiert oder erstellt), die Pakete (in der App: der Ordner Pacotes, jedes Paket darin), die vom Editor aufbewahrten Bilder, den Schnellspeicherstand, deine Archetypen, die Hinweise und Warnungen, Fensterpositionen und -größen, den Autor, den Exportordner und das automatische Speichern.",
    "Reset everything: the work on screen, the Workshop and the packages, the pictures kept, the quick save, archetypes, tips and warnings, window positions and sizes, author, export folder and autosave. The language stays.": "Alles zurücksetzen: die Arbeit auf dem Bildschirm, die Werkstatt und die Pakete, die aufbewahrten Bilder, den Schnellspeicherstand, Archetypen, Tipps und Warnungen, Fensterpositionen und -größen, Autor, Exportordner und automatisches Speichern. Die Sprache bleibt.",
