    "No condition: every time counts.": "Keine Bedingung: Jedes Mal zählt.",
    "+ add a condition…": "+ Bedingung hinzufügen …",
    "One at a time: every condition added must hold for the moment to count.": "Eine nach der anderen: Jede hinzugefügte Bedingung muss erfüllt sein, damit der Moment zählt.",
    "3. How it counts": "3. Wie es zählt",
    "Counting": "Zählweise",
    "Items gained": "Erhaltene Gegenstände",
    "Each item gained counts one.": "Jeder erhaltene Gegenstand zählt eins.",
    "A round counts once when it happens that many times in it.": "Eine Runde zählt einmal, wenn es in ihr so oft geschieht.",
    "It must happen every round; from that round in a row on, each round counts one.": "Es muss jede Runde geschehen; ab dieser Runde in Folge zählt jede Runde eins.",
    "Each time counts one.": "Jedes Mal zählt eins.",
    "The damage of each attack is added up.": "Der Schaden jedes Angriffs wird zusammengezählt.",
    "4. When the game offers it": "4. Wann das Spiel sie anbietet",
    "The game offers each hero two feats at a time, drawn among the ones available. A feat becomes available from its act and once the hero has completed that many feats of their own (0: from the start). The game spreads its own in steps: 0, 4, 8, 12 and 14.": "Das Spiel bietet jedem Helden zwei Errungenschaften auf einmal an, gezogen aus den verfügbaren. Eine Errungenschaft wird ab ihrem Akt verfügbar und sobald der Held so viele eigene Errungenschaften abgeschlossen hat (0: von Anfang an). Das Spiel verteilt seine eigenen in Rängen: 0, 4, 8, 12 und 14.",
    "5. Reward": "5. Belohnung",
    "Taken out (the game does not check them at this moment):": "Herausgenommen (das Spiel prüft sie in diesem Moment nicht):",
    "Size, position and mirror of the picture": "Größe, Position und Spiegelung des Bilds",
    "Adjust": "Anpassen",
    "Adjust the picture": "Bild anpassen",
    "Mirror (flip left to right)": "Spiegeln (horizontal)",
    "Whole picture": "Ganzes Bild",
    "Fill the frame": "Rahmen füllen",
    "Drag the picture to move it; the wheel or the slider changes its size; the arrows nudge it. What is outside the frame shows faint and is cut.": "Ziehe das Bild, um es zu verschieben; das Mausrad oder der Schieberegler ändert seine Größe; die Pfeiltasten schieben es. Was außerhalb des Rahmens liegt, wird blass gezeigt und abgeschnitten.",
    "Drag the picture to move it; the wheel or the slider changes its size; the arrows nudge it. What is outside the circle shows faint and is cut.": "Ziehe das Bild, um es zu verschieben; das Mausrad oder der Schieberegler ändert seine Größe; die Pfeiltasten schieben es. Was außerhalb des Kreises liegt, wird blass gezeigt und abgeschnitten.",
    "Made from the picture of the monster (below): ✎ Adjust fits it in the portrait.": "Aus dem Bild des Monsters erstellt (unten): ✎ Anpassen passt es ins Porträt ein.",
    "Made from the picture of the hero (below): ✎ Adjust fits it in the portrait.": "Aus dem Bild des Helden erstellt (unten): ✎ Anpassen passt es ins Porträt ein.",
    "A picture of its own for the card.": "Ein eigenes Bild für die Karte.",
    "The picture of the monster (above), standing on the board.": "Das Bild des Monsters (oben), auf dem Spielplan stehend.",
    "Another picture for the card": "Ein anderes Bild für die Karte",
    "Use the monster’s picture": "Das Bild des Monsters verwenden",
    "No picture to adjust.": "Kein Bild zum Anpassen.",
    "Could not open this picture.": "Dieses Bild konnte nicht geöffnet werden.",
    "Centre": "Zentrieren",
    "The app shows this text when the ability triggers; the players apply it.": "Die App zeigt diesen Text, wenn die Fähigkeit auslöst; die Spieler wenden ihn an.",
    "Stats": "Werte",
    "Name, picture, damage, damage types, ability of this part": "Name, Bild, Schaden, Schadensarten, Fähigkeit dieses Teils",
    "Not forged yet: Forge keeps it.": "Noch nicht geschmiedet: Schmieden behält es.",
    "new weapon": "neue Waffe",
    "box fixed": "Box fest",
    "A new weapon has one part of each: its stats are on the right (✎ Stats).": "Eine neue Waffe hat je ein Teil: Ihre Werte sind rechts (✎ Werte).",
    "Pick the parts in the middle column; ✎ Stats changes the damage, the ability and the rest of each one.": "Wähle die Teile in der mittleren Spalte; ✎ Werte ändert Schaden, Fähigkeit und den Rest jedes Teils.",
    "Language of the map (its flag shows in the community library)": "Sprache des Spielplans (ihre Flagge erscheint in der Community-Bibliothek)",
    "The language the campaign is written in: its flag shows in the community library": "Die Sprache, in der die Kampagne geschrieben ist: Ihre Flagge erscheint in der Community-Bibliothek",
    "the shop, the armory, the crafting": "der Händler, die Rüstkammer, die Herstellung",
    "(no condition yet)": "(noch keine Bedingung)",
    "+ Crossroads": "+ Weggabelung",
    "Crossroads {n}": "Weggabelung {n}",
    "Delete this crossroads": "Diese Weggabelung löschen",
    "Choose the exits of this crossroads": "Die Ausgänge dieser Weggabelung wählen",
    "The story goes one way or another, by the story variables (it goes after the selected card)": "Die Handlung geht den einen oder anderen Weg, je nach den Handlungsvariablen (kommt nach der gewählten Karte)",
    "+ Exit": "+ Ausgang",
    "Exit {n}": "Ausgang {n}",
    "exit {n}": "Ausgang {n}",
    "{n} exits": "{n} Ausgänge",
    "Goes to": "Führt zu",
    "In any other case": "In allen anderen Fällen",
    "Remove this exit": "Diesen Ausgang entfernen",
    "Pick a condition: without one, this exit never happens.": "Wähle eine Bedingung: ohne sie kommt dieser Ausgang nie.",
    "The story goes on by the first exit whose condition holds, checked from the top. When none holds, it goes on by “In any other case”. Once a card after it has played, the way taken stays for the rest of the campaign.": "Die Handlung geht über den ersten Ausgang weiter, dessen Bedingung erfüllt ist, von oben geprüft. Ist keine erfüllt, geht sie über „In allen anderen Fällen“ weiter. Sobald eine Karte danach gespielt wurde, bleibt der gewählte Weg für den Rest der Kampagne.",
    "An exit can also be linked on the canvas: drag from the ● of the Crossroads onto a card.": "Ein Ausgang lässt sich auch auf der Fläche verbinden: zieh vom ● der Weggabelung auf eine Karte.",
    "A tie counts as the highest: in a Crossroads, the first exit that holds wins.": "Ein Gleichstand zählt als die höchste: an einer Weggabelung gewinnt der erste erfüllte Ausgang.",
    "“{q}” is…": "„{q}“ ist …",
