    "Yes or no": "Ja oder nein",
    "yes or no": "ja oder nein",
    "Yes or no: a choice the party made. Number: a score that answers, boxes and map triggers add to or take from.": "Ja oder nein: eine Wahl der Gruppe. Zahl: ein Wert, den Antworten, Boxen und Auslöser der Spielpläne erhöhen oder senken.",
    "No story variable yet: in a question box, tick “Remember this answer”, or create one with the Story variables button.": "Noch keine Handlungsvariable: hake in einer Fragebox „Diese Antwort merken“ an oder lege eine mit dem Knopf Handlungsvariablen an.",
    "Only in a campaign: start one (top bar) and create its story variables.": "Nur in einer Kampagne: starte eine (obere Leiste) und lege ihre Handlungsvariablen an.",
    "The campaign has no story variable yet: create one with the Story variables button of the campaign screen.": "Die Kampagne hat noch keine Handlungsvariable: lege eine mit dem Knopf Handlungsvariablen auf dem Kampagnenbildschirm an.",
    "Played on its own, out of the campaign, the map counts every variable as at the start of the campaign.": "Allein gespielt, außerhalb der Kampagne, zählt der Spielplan jede Variable wie zu Beginn der Kampagne.",
    "To the campaign": "In die Kampagne",
